contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address recipient, uint256 amt) public {
        require(recipient != address(this));
        require(recipient != address(c));

        uint256 beforeBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(beforeBal >= amt);
        uint256 beforeRecBal = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        uint256 beforeSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool ok = c.transfer(recipient, amt); if (__ESBMC_reverted()) return;

        uint256 afterBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterRecBal = c.balanceOf(recipient); if (__ESBMC_reverted()) return;
        uint256 afterSupply = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(ok && afterBal == beforeBal - amt && afterRecBal == beforeRecBal + amt && afterSupply == beforeSupply);
    }
}

