    }

    function _run(address recipient, uint256 amt) internal {
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));
        uint256 beforeBal;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        vm.assume(beforeBal >= amt);
        uint256 beforeRecBal;
        try c.balanceOf(recipient) returns (uint256 __r) { beforeRecBal = __r; } catch { return; }
        uint256 beforeSupply;
        try c.totalSupply() returns (uint256 __r) { beforeSupply = __r; } catch { return; }
        bool ok;
        try c.transfer(recipient, amt) returns (bool __r) { ok = __r; } catch { return; }
